    const cyclePersonName=id=>{const p=list(cycleData.people).find(p=>String(p.id)===String(id));return p?`${p.full_name} · ${p.person_number}`:id||'待匹配';};
    const cycleShell=(title,description,...args)=>{const current=shell(title,`${description} 周期范围：${list(report.companies).map(c=>c.name).join('、')}；周期明细按当前帐套、公司及账号授权范围展示。`,...args);if(current)localeEditor(report.cycle.region_code,`${base}/cycles/${cycleId}/locale${cycleScope}`,report.scope?.can_write&&report.cycle.status!=='confirmed');return current;};
