    const form=container.querySelector('#bridgeForm');container.querySelector('[data-new-entity]').onclick=()=>dialogForm('建立已核实的法定主体',`${field('正式名称',input('name','','text','required'))}${field('统一代码（可留空）',input('credit_code'))}${field('地址（可留空）',input('address'))}${field('印章名称（可留空）',input('stamp_name'))}<p class="muted">主体用于明确发薪/社保关系，创建不会自动给任何门店绑定。</p>`,async(f,d)=>{await request('/api/foundation/bridge/entities',{method:'POST',body:{company_id:companyId,...values(f)}});d.close();toast('法定主体已建立，请明确选择对应关系');await draw();});if(!r.choices){form.querySelectorAll('input,select,button').forEach(el=>el.disabled=true);}
