// These serializers keep source labels separate from system identities.
export function flattenCompanyMetrics(rows){return list(rows).flatMap(row=>{const entries=Object.entries(row.metrics||{});return (entries.length?entries:[['',{}]]).map(([code,m])=>({...row,metric_code:code,...m,source_ref:row.source_ref||{},metric_source_ref:m.source_ref||row.source_ref||{}}));});}
const requiredNumber=(v,label)=>{if(v===''||v===null||v===undefined||!Number.isFinite(Number(v)))throw new Error(`${label}须填写数值`);return Number(v);};
export function buildPerformanceInputs(drafts){
  const grouped=new Map();for(const row of list(drafts.company_metrics)){
    const company_id=requiredNumber(row.company_id,'公司'),period=row.period;if(!/^\d{4}-\d{2}/.test(period||''))throw new Error('请选择指标月份');const key=company_id+':'+period.slice(0,7),entry=grouped.get(key)||{company_id,period:period.slice(0,7),metrics:{},source_saved_score:row.source_saved_score===''?null:row.source_saved_score??null,source_ref:row.source_ref||{}};
    if(row.metric_code){if(entry.metrics[row.metric_code])throw new Error('同公司同月指标编码重复');entry.metrics[row.metric_code]={value:requiredNumber(row.value,'指标实绩'),unit:row.unit||'ratio',status:row.status||'unverified',source_ref:row.metric_source_ref||row.source_ref||{}};if(row.target!==''&&row.target!==null&&row.target!==undefined)entry.metrics[row.metric_code].target=requiredNumber(row.target,'指标目标');}grouped.set(key,entry);
  }
  return {company_metrics:[...grouped.values()],person_months:list(drafts.person_months).map(r=>({...r,company_id:requiredNumber(r.company_id,'考核公司'),person_id:requiredNumber(r.person_id,'人员'),employment_id:requiredNumber(r.employment_id,'雇佣'),grade_id:requiredNumber(r.grade_id,'职级'),period:r.period?.slice(0,7),score_source:r.score_source||'company',eligibility_weight:requiredNumber(r.eligibility_weight??1,'资格折算'),eligibility_status:r.eligibility_status||'unverified',source_saved_score:r.source_saved_score===''?null:r.source_saved_score??null,source_saved_amount:r.source_saved_amount===''?null:r.source_saved_amount??null})),responsibilities:list(drafts.responsibilities).map(r=>({...r,company_id:requiredNumber(r.company_id,'责任公司'),person_id:requiredNumber(r.person_id,'负责人'),period:r.period?.slice(0,7),weight:requiredNumber(r.weight,'责任权重'),status:r.status||'unverified'}))};
}
export function verifyPerformanceProposal(proposed){const copy=structuredClone(proposed);for(const row of list(copy.company_metrics))for(const metric of Object.values(row.metrics||{}))if(metric.status!=='source_error'&&metric.value!==null&&metric.value!==''&&Number.isFinite(Number(metric.value)))metric.status='verified';for(const row of list(copy.person_months))row.eligibility_status='verified';for(const row of list(copy.responsibilities))if(row.status!=='source_error')row.status='verified';return copy;}
