async function performanceResults(env){
  const {base,cycleId,report,tabs,companyName,personName,shell,draw,request,container,toast,download,scopeQuery=''}=env,cycle=report.cycle,locked=cycle.status==='confirmed';
  shell('绩效计算与复核','公司分数、人员月结果、期间奖金分别保留，按实际版本确认。',tabs,`<section class="card"><div class="toolbar"><h2>${esc(cycle.name)} ${status(cycle.status)} · 版本 ${esc(cycle.result_version||0)}</h2><button data-calc class="primary" ${report.scope?.can_write&&!locked?'':'disabled'}>计算本期奖金</button><button data-confirm-result ${report.scope?.can_confirm?'':'disabled'}>核验并确认此版本</button><button data-export-result>导出结果</button><button data-to-payroll ${locked?'':'disabled'}>查看工资候选项</button></div><div class="detail-facts"><span>可见奖金人数<b>${esc(report.totals?.visible_people??0)}</b></span><span>就绪人数<b>${esc(report.totals?.ready_people??0)}</b></span><span>奖金合计<b>${num(report.totals?.amount)} ${esc(cycle.currency_code)}</b></span></div>${report.scope?.partial?'<p class="notice">当前仅是授权范围内的局部结果。</p>':''}${issuesHtml(report.issues)}<div id="performanceResults"></div><div id="payrollCandidates"></div></section>`);
  const kindLabels={company:'门店月度分数',company_score:'门店月度分数',person_month:'人员月度结果',person_bonus:'期间奖金汇总'};table(container.querySelector('#performanceResults'),[{label:'类型',render:r=>esc(kindLabels[r.kind]||r.kind)},{label:'人员',render:r=>esc(r.person_id?r.full_name||personName(r.person_id):'—')},{label:'公司',render:r=>esc(companyName(r.company_id))},{label:'月份',key:'period'},{label:'达成度',render:r=>r.score===null?'—':`${(Number(r.score)*100).toFixed(2)}%`},{label:'评级',key:'rating'},{label:'本次选定奖金',render:r=>exactAmount(r.amount)},{label:'方案一对照',render:r=>r.kind==='person_bonus'?exactAmount(r.details?.monthly_bonus_average):'—'},{label:'方案二对照',render:r=>r.kind==='person_bonus'?exactAmount(r.details?.average_score_last_grade):'—'},{label:'两方案差额',render:r=>r.kind==='person_bonus'?exactAmount(r.details?.difference):'—'},{label:'核验',render:r=>`<button class="text-button" data-perf-detail="${esc(r.id)}">${r.issues?.length?'待处理 '+r.issues.length+' 项':'查看依据'}</button>`}],list(report.results));
  container.querySelector('#performanceResults').onclick=e=>{const b=e.target.closest('[data-perf-detail]');if(!b)return;const r=report.results.find(r=>String(r.id)===b.dataset.perfDetail),d=dialogForm('计算依据与来源差异',`${issuesHtml(r.issues)}<pre class="source-json">${esc(jsonText(r.detail||r.details||r))}</pre>`,async(f,d)=>d.close());d.querySelector('.dialog-footer button.primary').textContent='关闭';};
  container.querySelector('[data-calc]').onclick=e=>action(e.target,async()=>{await request(`${base}/cycles/${cycleId}/calculate${scopeQuery}`,{method:'POST',body:{}});await draw();},toast);
  container.querySelector('[data-confirm-result]').onclick=()=>dialogForm(`确认绩效结果版本 ${cycle.result_version}`,`${field('核验依据',textarea('reason','','rows="4" required'))}${checkbox('ack','我已核验本期方案、来源差异、完整公司范围及人员结果')}`,async(f,d)=>{if(!f.elements.ack.checked)throw new Error('请先核验并勾选确认');await request(`${base}/cycles/${cycleId}/confirm${scopeQuery}`,{method:'POST',body:{result_version:cycle.result_version,reason:f.elements.reason.value}});d.close();toast('结果版本已确认，可在工资批次中选用');await draw();});
  container.querySelector('[data-export-result]').onclick=e=>action(e.target,()=>download(`${base}/cycles/${cycleId}/export.csv${scopeQuery}`,'绩效结果.csv'),toast);
  container.querySelector('[data-to-payroll]').onclick=e=>action(e.target,async()=>{const r=await request(`${base}/cycles/${cycleId}/payroll-candidates${scopeQuery}`,{method:'POST',body:{}}),h=container.querySelector('#payrollCandidates');h.innerHTML='<h3>已确认工资候选项</h3><p class="muted">只读取候选项。请进入“薪酬核算”的目标批次选用本周期，再重新试算；不会自动发薪。</p><div data-candidate-table></div>';table(h.querySelector('[data-candidate-table]'),[{label:'人员',render:r=>esc(personName(r.person_id))},{label:'公司',render:r=>esc(companyName(r.company_id))},{label:'工资月',key:'period'},{label:'奖金原额',render:r=>exactAmount(r.amount_exact??r.amount)}],list(r.candidates));},toast);
}
function renderPerformanceImport(env){
  const {preview:p,file,host,companies,people,grades,employments,personName,companyName,request,path,state,toast,applyProposal,rerender,loadScheme}=env;if(!p)return;
  host.innerHTML=`<h3>来源预检</h3><p class="muted">${esc(p.notice||'来源缓存不自动核验；姓名只供核对，原表序号只作本次映射键。')}</p>${issuesHtml(p.issues)}${p.source_summary?`<p>外部公式 ${esc(p.source_summary.external_formula_count??0)}；错误缓存 ${esc(p.source_summary.error_cell_count??0)}。这些是源工作簿证据，不代表规则获批。</p>`:''}${notesHtml(p.warnings,'来源与映射说明')}${p.rules_proposal?'<p><button data-source-rules>载入季度绩效来源模板规则（需选择启用）</button></p>':''}<div data-source-errors></div><div data-import-mapping></div><div data-import-preview></div><div data-import-apply></div>`;
  host.querySelector('[data-source-rules]')?.addEventListener('click',()=>loadScheme(p.rules_proposal));
  if(list(p.source_summary?.error_cells).length)table(host.querySelector('[data-source-errors]'),[{label:'工作表',key:'sheet'},{label:'单元格',key:'cell'},{label:'源错误',key:'error'}],p.source_summary.error_cells);
  if(p.candidates){
    const c=p.candidates||{},allPeople=list(c.people),companyLabels=[...new Set([...list(c.companies).map(x=>typeof x==='string'?x:x.label||x.company_label),...allPeople.flatMap(x=>list(x.months).map(m=>m.company_label))].filter(Boolean))],gradeLabels=[...new Set(allPeople.flatMap(x=>list(x.months).map(m=>m.grade_label)).filter(Boolean))],mapping=state.perfMapping||{companies:{},people:{},grades:{},employments:{}};
    const h=host.querySelector('[data-import-mapping]');h.innerHTML='<h3>明确映射</h3><p class="muted">逐项选择系统身份。月度考核归属不会写成任职；不凭同名自动合并。汇总/重复公司行可逐行明确排除。</p><form data-map-form><nav class="business-tabs" aria-label="来源映射步骤"><button type="button" data-map-tab="companies" class="primary">门店公司</button><button type="button" data-map-tab="grades">职级</button><button type="button" data-map-tab="people">人员身份</button><button type="button" data-map-tab="employments">逐月雇佣</button><button type="button" data-map-tab="responsibilities">管理责任</button></nav><section data-map-section="companies"><details open><summary>1. 按源标签对应门店</summary><div data-map-companies></div></details><details><summary>2. 逐行核验、覆盖或排除公司月行</summary><div data-map-company-rows></div></details></section><section data-map-section="grades" hidden><h4>原职级与系统职级</h4><div data-map-grades></div></section><section data-map-section="people" hidden><h4>明确人员身份及分数来源</h4><div data-map-people></div></section><section data-map-section="employments" hidden><h4>逐月考核公司与雇佣</h4><div data-map-employments></div></section><section data-map-section="responsibilities" hidden><h4>管理责任公司与权重（需明确清单）</h4><div data-map-responsibilities></div></section><p><button type="submit">用明确映射重新预检</button></p></form>';
    h.querySelectorAll('[data-map-tab]').forEach(button=>button.onclick=()=>{h.querySelectorAll('[data-map-section]').forEach(section=>section.hidden=section.dataset.mapSection!==button.dataset.mapTab);h.querySelectorAll('[data-map-tab]').forEach(b=>b.classList.toggle('primary',b===button));});
    const add=(target,rows,choices,stored)=>{const t=h.querySelector(target);rows.forEach(([key,label])=>{const el=document.createElement('label');el.className='mapping-row';el.innerHTML=`<span>${esc(label)}</span>${select('mapped',choices,stored[key])}`;el.dataset.key=key;t.append(el);});};
    add('[data-map-companies]',companyLabels.map(l=>[l,l]),companies,mapping.companies);add('[data-map-grades]',gradeLabels.map(l=>[l,l]),grades,mapping.grades);add('[data-map-people]',allPeople.map(x=>[String(x.source_ordinal),`${x.source_ordinal} · ${x.name_label} · 原行${x.source_row}`]),people.map(p=>({...p,name:`${p.full_name} · ${p.person_number}`})),mapping.people);
    const get=target=>Object.fromEntries([...h.querySelectorAll(target+' .mapping-row')].filter(el=>el.querySelector('select').value).map(el=>[el.dataset.key,Number(el.querySelector('select').value)]));
    mapping.company_rows||={};mapping.person_companies||={};mapping.score_sources||={};mapping.exclude_company_rows||=[];mapping.exclude_people||=[];
    const companyRows=h.querySelector('[data-map-company-rows]');table(companyRows,[{label:'源行',render:r=>esc(r.candidate_key)},{label:'源标签',key:'label'},{label:'源缓存分数',render:r=>num(r.source_saved_score)},{label:'原位置',render:r=>esc(`${r.source_ref?.sheet||''}!${r.source_ref?.range||''}`)},{label:'明确处理',render:r=>`<select data-company-row="${esc(r.candidate_key)}">${opts([{id:'_label',name:'沿用已选标签映射'},{id:'_exclude',name:'排除：汇总/重复/非考核公司'},...companies],mapping.exclude_company_rows.includes(r.candidate_key)?'_exclude':mapping.company_rows[r.candidate_key]||'_label')}</select>`}],list(c.companies));companyRows.onchange=e=>{const key=e.target.dataset.companyRow;if(!key)return;mapping.exclude_company_rows=mapping.exclude_company_rows.filter(k=>k!==key);delete mapping.company_rows[key];if(e.target.value==='_exclude')mapping.exclude_company_rows.push(key);else if(e.target.value&&e.target.value!=='_label')mapping.company_rows[key]=Number(e.target.value);};
    h.querySelectorAll('[data-map-people] .mapping-row').forEach(row=>{const key=row.dataset.key,box=document.createElement('div');box.innerHTML=`${select('score_source',[{id:'company',name:'按公司得分'},{id:'management',name:'管理责任加权'}],mapping.score_sources[key],'分数来源待明确')}${checkbox('exclude','明确排除本次导入的该人员',mapping.exclude_people.includes(key))}`;box.querySelector('[name=score_source]').onchange=e=>mapping.score_sources[key]=e.target.value;box.querySelector('[name=exclude]').onchange=e=>{mapping.exclude_people=mapping.exclude_people.filter(k=>k!==key);if(e.target.checked)mapping.exclude_people.push(key);drawEmployments();};row.append(box);});
    const drawEmployments=()=>{mapping.companies=get('[data-map-companies]');mapping.people=get('[data-map-people]');mapping.grades=get('[data-map-grades]');mapping.employments={...mapping.employments,...get('[data-map-employments]')};const target=h.querySelector('[data-map-employments]');target.innerHTML='';for(const p of allPeople.filter(p=>!mapping.exclude_people.includes(p.source_ordinal)))for(const m of list(p.months)){const key=`${p.source_ordinal}:${m.period}`,pid=mapping.people[p.source_ordinal],cid=mapping.person_companies[key]||mapping.companies[m.company_label];add('[data-map-employments]',[[key,`${p.name_label} / ${m.period} / 源店：${m.company_label}`]],employments.filter(e=>String(e.person_id)===String(pid)&&String(e.company_id)===String(cid)).map(e=>({...e,name:`${personName(e.person_id)} / ${companyName(e.company_id)} / ${day(e.hire_date)} 入职${e.leave_date?' / '+day(e.leave_date)+' 离职':''}`})),mapping.employments);const row=target.lastElementChild,company=document.createElement('div');company.innerHTML=select('person_company',companies,mapping.person_companies[key],'沿用源标签公司映射');company.querySelector('select').onchange=e=>{if(e.target.value)mapping.person_companies[key]=Number(e.target.value);else delete mapping.person_companies[key];drawEmployments();};row.append(company);}paginateMapping(target);};
    const responsibilityEditor=h.querySelector('[data-map-responsibilities]');editableGrid(responsibilityEditor,[{key:'person_id',label:'负责人',choices:people.map(p=>({...p,name:personName(p.id)}))},{key:'company_id',label:'责任公司',choices:companies},{key:'period',label:'月份',type:'month'},{key:'weight',label:'责任权重',type:'number'},{key:'source_ref',label:'责任依据（JSON）',type:'json'}],list(mapping.responsibilities));
    h.querySelectorAll('[data-map-companies] select,[data-map-people] select[name=mapped]').forEach(s=>s.onchange=drawEmployments);drawEmployments();for(const selector of ['[data-map-companies]','[data-map-grades]','[data-map-people]'])paginateMapping(h.querySelector(selector));h.querySelector('form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{mapping.companies=get('[data-map-companies]');mapping.people=get('[data-map-people]');mapping.grades=get('[data-map-grades]');mapping.employments=get('[data-map-employments]');mapping.responsibilities=readGrid(responsibilityEditor);state.perfMapping=mapping;state.perfPreview=await request(path,{method:'POST',body:{...file,mapping}});rerender();},toast);};
  }
  if(list(p.preview).length)table(host.querySelector('[data-import-preview]'),[{label:'原行',key:'row'},{label:'类型',key:'record_type'},{label:'公司',render:r=>esc(companyName(r.company_id))},{label:'人员',render:r=>esc(r.person_id?personName(r.person_id):'—')},{label:'月份',key:'period'},{label:'匹配',render:r=>esc(['matched','matched_unverified'].includes(r.status)?'已匹配，仍待核验':r.status==='excluded'?'明确排除':'待处理')}],p.preview);
  if(p.proposed){const t=host.querySelector('[data-import-apply]');t.innerHTML=`<p>候选：门店月实绩 ${list(p.proposed.company_metrics).length} 条；人员月归属 ${list(p.proposed.person_months).length} 条；管理责任 ${list(p.proposed.responsibilities).length} 条。</p>${checkbox('verify_import','我已逐项核验候选实绩、人员资格和责任权重（仅限实际提供的数据）')}<p><button data-load-proposal ${p.can_apply?'':'disabled'}>载入候选到本期编辑区</button></p><p class="muted">未勾选时保留候选原有状态。载入会替换编辑区，随后单独保存。只有缓存总分的门店，仍须补充方案要求的实绩指标。</p>`;t.querySelector('[data-load-proposal]').onclick=()=>applyProposal(t.querySelector('[name=verify_import]').checked?verifyPerformanceProposal(p.proposed):structuredClone(p.proposed));}
}
function editableGrid(host,columns,rows,{allowAdd=true,allowRemove=true}={}){
  host._columns=columns;host._records=structuredClone(rows);let page=1;const pageSize=20;
  host.innerHTML=`<div class="table-toolbar"><span data-grid-count></span></div><p class="form-error" data-grid-error hidden></p><div class="table-wrap"><table><thead><tr>${columns.map(c=>`<th>${esc(c.label)}</th>`).join('')}<th></th></tr></thead><tbody></tbody></table></div><div class="table-pagination"><button type="button" data-grid-prev>上一页</button><span data-grid-page></span><button type="button" data-grid-next>下一页</button><button type="button" data-add>添加一行</button></div>`;
  host._flush=()=>{for(const row of host.querySelectorAll('tbody tr'))host._records[Number(row.dataset.index)]={...row._initial,...Object.fromEntries([...row.querySelectorAll('[name]')].map(el=>{const c=columns.find(c=>c.key===el.name);let value=el.type==='checkbox'?el.checked:el.value;if(c.type==='number'&&value!=='')value=requiredNumber(value,c.label);if(c.type==='json'){try{value=JSON.parse(value||(c.key==='bands'?'[]':'{}'));}catch{throw new Error(`${c.label}不是有效JSON`);}}return[el.name,value];}))};};
  const operate=fn=>{const error=host.querySelector('[data-grid-error]');try{host._flush();error.hidden=true;fn();draw();}catch(e){error.textContent=e.message;error.hidden=false;}};
  const draw=()=>{const pages=Math.max(1,Math.ceil(host._records.length/pageSize));page=Math.min(page,pages);const tbody=host.querySelector('tbody');tbody.innerHTML='';host._records.slice((page-1)*pageSize,page*pageSize).forEach((r,offset)=>{const index=(page-1)*pageSize+offset,row=document.createElement('tr');row._initial=r;row.dataset.index=index;row.innerHTML=columns.map(c=>{let v=r[c.key]??'';if(c.type==='month')v=String(v).slice(0,7);return `<td>${c.type==='check'?`<input name="${esc(c.key)}" type="checkbox" aria-label="${esc(c.label)}" ${v?'checked':''}>`:c.type==='typed'&&r.value_type==='boolean'?select(c.key,[{id:'true',name:'是 true'},{id:'false',name:'否 false'}],String(v),'未明确'):c.choices?select(c.key,c.choices,v):c.options?select(c.key,c.options.map(([id,name])=>({id,name})),String(v)):c.type==='json'?textarea(c.key,v===''?'':JSON.stringify(v),'rows="2" aria-label="'+esc(c.label)+'"'):input(c.key,v,c.type==='typed'?(r.value_type==='number'?'number':'text'):c.type||'text',`${c.readonly?'readonly':''} aria-label="${esc(c.label)}" ${c.type==='number'||c.type==='typed'&&r.value_type==='number'?'step="any"':''}`)}</td>`;}).join('')+'<td><button type="button" data-remove aria-label="移除此行">×</button></td>';row.querySelector('[data-remove]').hidden=!allowRemove;row.querySelector('[data-remove]').onclick=()=>operate(()=>host._records.splice(index,1));tbody.append(row);});host.querySelector('[data-grid-count]').textContent=`共 ${host._records.length} 条可编辑记录`;host.querySelector('[data-grid-page]').textContent=`第 ${page} / ${pages} 页`;host.querySelector('[data-grid-prev]').disabled=page===1;host.querySelector('[data-grid-next]').disabled=page===pages;if(host._readOnly)host.querySelectorAll('input,select,textarea,[data-add],[data-remove]').forEach(el=>el.disabled=true);};
  host.querySelector('[data-add]').hidden=!allowAdd;host._readOnly=false;host._setReadOnly=value=>{host._readOnly=value;draw();};
  host.querySelector('[data-grid-prev]').onclick=()=>operate(()=>page--);host.querySelector('[data-grid-next]').onclick=()=>operate(()=>page++);host.querySelector('[data-add]').onclick=()=>operate(()=>{host._records.push({});page=Math.ceil(host._records.length/pageSize);});draw();
}
function readGrid(host){host._flush();return host._records;}
